import{_ as o,o as t,c as a,ae as i}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Executor Workspace Tooling Failure Report","description":"","frontmatter":{},"headers":[],"relativePath":"historical/2026-05-remediation-dossiers/executor-workspace-tooling-failure-report.md","filePath":"historical/2026-05-remediation-dossiers/executor-workspace-tooling-failure-report.md"}'),r={name:"historical/2026-05-remediation-dossiers/executor-workspace-tooling-failure-report.md"};function s(c,e,n,l,d,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p><strong>Historical/Audit Artifact — Not Current Operator Instructions</strong><br> This page records an incident report from an earlier stage. It is not authoritative for current Saivage v3 behavior unless a current active doc explicitly revalidates it against current source and tests.</p></blockquote><h1 id="executor-workspace-tooling-failure-report" tabindex="-1">Executor Workspace Tooling Failure Report <a class="header-anchor" href="#executor-workspace-tooling-failure-report" aria-label="Permalink to &quot;Executor Workspace Tooling Failure Report&quot;">​</a></h1><p>Date: 2026-05-15</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>The failed the target project task was not caused by the modeling code requested by the card. It exposed a higher-level execution design problem in Saivage v3: executor agents were instructed to create files and run commands, but the live agent adapter did not reliably provide a first-class workspace tool surface that could do that work in the project root.</p><p>The immediate failed card was <code>code-3</code>, &quot;Implement expanding-window baseline evaluation&quot;. Its recorded error said the executor could not enter <code>/work/target-project</code>. A deeper inspection showed that several earlier cards were marked done even though their promised files did not exist in <code>/work/target-project</code> or the host <code>target-project</code> checkout. Runtime events also logged artifact registration failures such as &quot;Source file not found&quot; for files the agents claimed to have produced.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><ul><li>The live service is configured with <code>WorkingDirectory=/work/target-project</code>.</li><li>The live project directory contained <code>.saivage</code> and <code>.saivage-work</code> state, but no generated project files such as <code>pyproject.toml</code>, <code>src/target_v2/...</code>, <code>tests/...</code>, or docs.</li><li><code>code-3</code> failed before implementation because the executor reported that <code>/work/target-project</code> was unavailable for <code>cd</code>.</li><li>Earlier completed cards registered artifacts whose source files were missing from the real project root.</li><li>The live model routing prioritized <code>openai-codex</code>, and <code>AgentAdapter.createLlmCallFn()</code> stripped tool definitions for that provider before making calls.</li><li>The executor prompt and runtime skill context advertised command/file capabilities such as process execution, but <code>AgentAdapter</code> only handled <code>load_skill</code> and <code>mcp_tool_call</code>. The live project only had Playwright configured as an MCP server, not filesystem or shell tools.</li></ul><h2 id="root-cause" tabindex="-1">Root Cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root Cause&quot;">​</a></h2><p>The runtime treated executor output JSON as an authoritative report of completed work. It then attempted to register any listed artifacts, but artifact registration failures were logged as secondary errors and did not invalidate a successful executor result.</p><p>This created a false-success path:</p><ol><li>Planner created executable cards.</li><li>Executor model received prompts saying it should write files and run commands.</li><li>The adapter did not give the executor native project file and shell tools in the live provider path.</li><li>The model could still return JSON claiming work was done.</li><li>Runtime marked the card done before or despite missing artifact source files.</li><li>Later cards depended on files that did not exist, exposing the mismatch.</li></ol><p>The failed <code>cd /work/target-project</code> was therefore a symptom. The design issue was that the execution layer had no enforced, project-scoped tool contract for concrete filesystem and command work.</p><h2 id="design-findings" tabindex="-1">Design Findings <a class="header-anchor" href="#design-findings" aria-label="Permalink to &quot;Design Findings&quot;">​</a></h2><h3 id="missing-execution-boundary" tabindex="-1">Missing Execution Boundary <a class="header-anchor" href="#missing-execution-boundary" aria-label="Permalink to &quot;Missing Execution Boundary&quot;">​</a></h3><p>Saivage has a process runner, artifact registry, card store, and agent session persistence, but the real LLM adapter did not expose project-scoped file and command tools as native function tools. The prompt implied capabilities that were not actually available.</p><h3 id="provider-specific-tool-disablement" tabindex="-1">Provider-Specific Tool Disablement <a class="header-anchor" href="#provider-specific-tool-disablement" aria-label="Permalink to &quot;Provider-Specific Tool Disablement&quot;">​</a></h3><p>The OpenAI Codex transport supports tool definitions, but the adapter removed tools for <code>openai-codex</code>. Since the live configuration gave that provider top priority, the executor was normally invoked without tools.</p><h3 id="tool-call-round-trip-weakness" tabindex="-1">Tool-Call Round-Trip Weakness <a class="header-anchor" href="#tool-call-round-trip-weakness" aria-label="Permalink to &quot;Tool-Call Round-Trip Weakness&quot;">​</a></h3><p>Tool outputs were persisted as generic messages without preserving provider tool call identifiers. That is fragile for providers that require a tool output to reference the original function call.</p><h3 id="artifact-registration-was-too-weak-as-verification" tabindex="-1">Artifact Registration Was Too Weak As Verification <a class="header-anchor" href="#artifact-registration-was-too-weak-as-verification" aria-label="Permalink to &quot;Artifact Registration Was Too Weak As Verification&quot;">​</a></h3><p>Artifact registration copied existing files into <code>.saivage-work</code>, but missing source files only produced logged errors. This made artifact failure visible in logs but not strong enough to prevent false completion.</p><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to &quot;Impact&quot;">​</a></h2><ul><li>Cards can be marked done without corresponding files existing in the project root.</li><li>Downstream cards can fail for environmental reasons that are really earlier false completions.</li><li>Operators see a plausible card tree but an empty or incomplete workspace.</li><li>Live project recreation is unreliable because the system lacks a hard connection between executor claims and workspace mutations.</li></ul><h2 id="corrective-direction" tabindex="-1">Corrective Direction <a class="header-anchor" href="#corrective-direction" aria-label="Permalink to &quot;Corrective Direction&quot;">​</a></h2><p>The clean fix is to make workspace mutation an explicit runtime capability instead of relying on prompts or external MCP availability. Executor agents must use native project-scoped tools for file and command work, and those tool calls must be serialized correctly for the selected provider.</p>',26)])])}const m=o(r,[["render",s]]);export{h as __pageData,m as default};
